// Validate incoming payload from the frontend
const body = $input.first().json.body || {};
const transcript = (body.transcript || '').trim();

if (!transcript) {
  throw new Error('Missing "transcript" field in request body.');
}

const prompt = `You are a call-center QA analyst. Analyze the following conversation transcript and return ONLY a single valid JSON object (no markdown fences, no commentary) matching exactly this schema:

{
  "overall_sentiment": "Positive" | "Negative" | "Neutral",
  "overall_confidence": number (0-1),
  "sentences": [ { "text": string, "sentiment": "Positive"|"Negative"|"Neutral", "score": number (-1 to 1), "speaker": string | null } ],
  "emotions": [ { "label": string, "intensity": number (0-1) } ],
  "summary": string,
  "resolution_status": "Resolved" | "Unresolved" | "Unclear",
  "escalation_risk": "Low" | "Medium" | "High",
  "csat_estimate": number (1-5),
  "agent_empathy_score": number (0-100),
  "key_topics": [string],
  "action_items": [string]
}

Split the transcript into individual utterances in original order for "sentences". Capture speaker labels like "Agent:" / "Customer:" when present. Return ONLY the JSON object.

Transcript:
"""
${transcript}
"""`;

return [{ json: { prompt, transcript } }];

// Extract and safely parse the JSON object the model returned
const response = $input.first().json;
const textBlock = (response.content || []).find(b => b.type === 'text');

if (!textBlock) {
  throw new Error('No text content returned from the model.');
}

let cleaned = textBlock.text.replace(/```json|```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('Could not parse model output as JSON: ' + cleaned.slice(0, 200));
  parsed = JSON.parse(match[0]);
}

return [{ json: parsed }];
